H.background();
const g = 9.8;
const h0 = P.h0;
const tFall = Math.sqrt(2 * h0 / g);
const period = tFall + 1.2;
const tc = (t % period);
const tf = Math.min(tc, tFall);
const y = h0 - 0.5 * g * tf * tf;
const vy = -g * tf;
const groundY = 500, topY = 80;
const yMax = Math.max(h0, 1);
const py = H.map(Math.max(0, y), 0, yMax, groundY, topY);
const ballX = H.W / 2;
H.line(120, groundY, H.W - 120, groundY, { color: H.colors.grid, width: 3 });
H.text("ground", H.W - 120, groundY + 18, { color: H.colors.sub, size: 11, align: "right" });
for (let i = 0; i <= 4; i++) {
  const hv = yMax * i / 4;
  const ty = H.map(hv, 0, yMax, groundY, topY);
  H.line(115, ty, 125, ty, { color: H.colors.axis, width: 1 });
  H.text(hv.toFixed(0) + " m", 108, ty, { color: H.colors.sub, size: 11, align: "right", baseline: "middle" });
}
H.line(ballX, topY, ballX, groundY, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.circle(ballX, py, 16, { fill: H.colors.accent });
H.arrow(ballX, py, ballX, py - vy * 4, { color: H.colors.warn, width: 3 });
H.text("Free fall: y = h0 - 1/2 g t^2,  v = -g t", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("g = 9.8 m/s^2,  released from rest", 24, 52, { color: H.colors.sub, size: 13 });
H.text("h0 = " + h0.toFixed(1) + " m   t_fall = " + tFall.toFixed(2) + " s", 24, 74, { color: H.colors.sub, size: 13 });
H.text("t = " + tf.toFixed(2) + " s", 24, 96, { color: H.colors.sub, size: 13 });
H.text("y = " + Math.max(0, y).toFixed(1) + " m   v = " + vy.toFixed(1) + " m/s", 24, 118, { color: H.colors.accent, size: 13 });
